//! `routes![]` collection macro implementation.
//!
//! Expands `routes![handler_a, handler_b]` into a `Vec<Route>` by calling
//! the companion `__autumn_route_info_{name}()` functions generated by the
//! route attribute macros.
//!
//! In the `autumn contracts export` pass it also writes a marker with the
//! handlers it registers. An `#[endpoint]` that no marker names is not
//! served.

use proc_macro2::TokenStream;
use quote::quote;
use syn::{Path, Token, punctuated::Punctuated};

use crate::wire::ir::{RoutesDescriptor, stable_key};
use crate::wire::store;

/// Expand a comma-separated list of handler paths into a `Vec<Route>`.
///
/// Each path's last segment is transformed from `name` to
/// `__autumn_route_info_name`, so module-qualified paths like `users::list`
/// become `users::__autumn_route_info_list`.
pub fn routes_macro(input: TokenStream) -> TokenStream {
    let written = write_marker(&input);
    let track = store::track_contract_dir();
    let routes = crate::collect::collect_companions(input, "__autumn_route_info_");
    quote! {
        {
            #track
            #written
            #routes
        }
    }
}

/// Write the marker in the export pass. A normal build has no reader for
/// it, so it writes nothing.
fn write_marker(input: &TokenStream) -> TokenStream {
    if !store::strict() {
        return TokenStream::new();
    }
    let Some(dir) = store::contract_dir() else {
        return TokenStream::new();
    };
    let krate = std::env::var("CARGO_PKG_NAME").unwrap_or_default();
    let module = input
        .clone()
        .into_iter()
        .next()
        .map(|t| store::source_module(t.span()))
        .unwrap_or_default();
    let Some(marker) = routes_descriptor(&krate, &module, input) else {
        return TokenStream::new();
    };
    let key = stable_key(&format!("{module} {input}"));
    store::write_outcome(store::write_routes(&dir, &marker, &key))
}

/// The marker for one `routes![…]` call, or `None` for an empty list or one
/// that does not parse.
#[must_use]
pub fn routes_descriptor(
    krate: &str,
    module: &str,
    input: &TokenStream,
) -> Option<RoutesDescriptor> {
    let paths = syn::parse::Parser::parse2(
        Punctuated::<Path, Token![,]>::parse_terminated,
        input.clone(),
    )
    .ok()?;
    let handlers: Vec<String> = paths
        .iter()
        .map(|p| {
            let joined = p
                .segments
                .iter()
                .map(|s| s.ident.to_string())
                .collect::<Vec<_>>()
                .join("::");
            // A leading `::` marks an absolute path. It stays.
            if p.leading_colon.is_some() {
                format!("::{joined}")
            } else {
                joined
            }
        })
        .collect();
    if handlers.is_empty() {
        return None;
    }
    Some(RoutesDescriptor {
        krate: krate.to_owned(),
        module: module.to_owned(),
        handlers,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use quote::quote;

    #[test]
    fn the_marker_lists_each_handler_path_as_written() {
        let d = routes_descriptor(
            "catalog",
            "api",
            &quote! { get_item, items::create, mesh_catalog::list, },
        )
        .expect("a handler list");
        assert_eq!(d.krate, "catalog");
        assert_eq!(d.module, "api");
        assert_eq!(
            d.handlers,
            ["get_item", "items::create", "mesh_catalog::list"]
        );
    }

    #[test]
    fn an_absolute_handler_path_keeps_its_leading_colons() {
        let d = routes_descriptor("app", "", &quote! { ::catalog::list }).expect("a list");
        assert_eq!(d.handlers, ["::catalog::list"]);
    }

    #[test]
    fn an_empty_or_broken_list_has_no_marker() {
        assert!(routes_descriptor("catalog", "", &quote! {}).is_none());
        assert!(routes_descriptor("catalog", "", &quote! { 1 + }).is_none());
    }

    #[test]
    fn the_expansion_tracks_the_contract_dir_variable() {
        let out = routes_macro(quote! { get_item }).to_string();
        assert!(out.contains("AUTUMN_CONTRACT_DIR"), "{out}");
        assert!(out.contains("__autumn_route_info_get_item"), "{out}");
    }
}
